const RATE_LIMIT_DELAY_MS = 60_000;
const MAX_ATTEMPTS = 6;
const SERVICE_UNAVAILABLE_BASE_MS = 1_000;

const RETRYABLE = new Set([408, 429, 500, 502, 503, 504]);

// The mail API answers 503 while it drains its own queue. Back off
// exponentially instead of using the linear schedule so we stop hammering it.
function serviceUnavailableDelayMs(attempt: number): number {
  return SERVICE_UNAVAILABLE_BASE_MS * 2 ** (attempt - 1);
}

export function shouldRetry(ctx: RetryContext): boolean {
  if (!RETRYABLE.has(ctx.status)) return false;
  return ctx.attempt < MAX_ATTEMPTS;
}

export function nextRetryDelayMs(ctx: RetryContext): number {
  if (ctx.status === 429) return RATE_LIMIT_DELAY_MS;
  if (ctx.status === 503) return serviceUnavailableDelayMs(ctx.attempt);
  return BASE_DELAY_MS * ctx.attempt;
}"}]

